<!--
 * OAuth2 应用管理页面 — 管理 OAuth2 客户端应用注册信息
 *
 * @path apps\userinfo-web\src\views\oauth2\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * OAuth2 应用管理（列表页）
 * <p>OAuth2 客户端应用的列表页，消费后端契约 OAuth2ApplicationController
 * （src/api/oAuth2Application.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询应用列表，支持创建/编辑/重置密钥/删除等操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButton, YdForm, YdFormItem, YdInput, YdNumberFieldInput, YdRadioGroupItem, YdRadioGroup } from '@ydsz-core/ydsz-ui';
import { computed, h, reactive, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@ydsz-core/shared/utils';

import { showToast } from '@ydsz/notification';
import { YdConfirm } from '@ydsz-core/popup-ui';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import type { PageResponse } from '#/api/models';
import {
  deleteApi,
  getById,
  page,
  register,
  resetSecret,
  update,
} from '#/api/oAuth2Application';

defineOptions({ name: 'OAuth2Management' });

/**
 * OAuth2 客户端应用。
 *
 * @remarks
 * 后端 `OAuth2ApplicationController` 的响应在 OpenAPI 里只声明为未参数化的
 * `YdszResponse`，生成件（`#/api/oAuth2Application.ts`）因此把返回类型退化成了
 * `'CONFIDENTIAL' | 'PUBLIC'` 这种枚举联合，拿不到真实字段。这里按接口实际响应体
 * 声明本视图需要的形状，并在调用点做一次边界转换；契约补上 schema 后应改用生成类型。
 */
interface OAuth2Application {
  /** 允许的 audience 列表 */
  allowedAudiences?: string[];
  /** 允许的 scope 列表 */
  allowedScopes?: string[];
  /** 客户端标识，同时用作记录主键 */
  clientId?: string;
  /** 客户端密钥（列表接口可能不返回） */
  clientSecret?: string;
  /** 应用名称 */
  clientName?: string;
  /** 客户端类型 */
  clientType?: 'CONFIDENTIAL' | 'PUBLIC';
  /** 备注说明 */
  description?: string;
  /** 回调地址列表 */
  redirectUris?: string[];
  /** ENABLED / DISABLED */
  status?: string;
}

const logger = createLogger('userinfo-oauth2');
const { t } = useI18n();

/** OAuth2 应用状态判断 */
function isEnabled(status?: string): boolean {
  return status === 'ENABLED';
}

/** 脱敏展示 clientSecret */
function maskSecret(secret?: string): string {
  if (!secret || secret.length <= 8) return '********';
  return `${secret.slice(0, 4)}****${secret.slice(-4)}`;
}

// ========== VxeTable 配置 ==========
const gridOptions: VxeTableGridOptions<OAuth2Application> = {
  columns: [
    { type: 'seq', width: 50, title: t('page.rowIndex') },
    { field: 'clientId', title: 'Client ID', width: 200 },
    { field: 'clientName', title: t('oauth2.clientName'), minWidth: 140 },
    {
      field: 'clientType',
      title: t('oauth2.clientType'),
      width: 100,
      slots: {
        default: ({ row }) => {
          const isConfidential = row.clientType === 'CONFIDENTIAL';
          return h(
            YdBadge,
            { variant: isConfidential ? 'default' : 'secondary', class: 'text-xs' },
            () => (isConfidential ? t('oauth2.confidential') : t('oauth2.public')),
          );
        },
      },
    },
    {
      field: 'redirectUris',
      title: t('oauth2.redirectUris'),
      minWidth: 180,
      formatter: ({ row }) => {
        const uris = row.redirectUris;
        if (!uris || uris.length === 0) return '-';
        return uris.join(', ');
      },
    },
    {
      field: 'allowedScopes',
      title: t('oauth2.scopes'),
      width: 140,
      formatter: ({ row }) => {
        const scopes = row.allowedScopes;
        if (!scopes || scopes.length === 0) return '-';
        return scopes.join(', ');
      },
    },
    {
      field: 'clientSecret',
      title: t('oauth2.secretMasked'),
      width: 140,
      formatter: ({ row }) => maskSecret(row.clientSecret),
    },
    {
      field: 'status',
      title: t('page.status'),
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            YdBadge,
            { variant: enable ? 'default' : 'destructive', class: enable ? 'bg-green-500 text-white hover:bg-green-600' : 'text-xs' },
            () => (enable ? t('page.enabled') : t('page.disabled')),
          );
        },
      },
    },
    {
      field: 'action',
      title: t('page.operation'),
      width: 220,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1 flex-wrap' }, [
            h(
              YdButton,
              { size: 'sm', variant: 'link', onClick: () => handleEdit(row) },
              () => t('page.edit'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', class: 'border-yellow-500 text-yellow-600 dark:text-yellow-400', onClick: () => handleResetSecret(row) },
              () => t('oauth2.resetSecret'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', class: 'text-destructive', onClick: () => handleDelete(row) },
              () => t('page.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = (await page({
          status: formValues?.status || undefined,
          keyword: formValues?.keyword || undefined,
          pageNum: _page?.currentPage,
          pageSize: _page?.pageSize,
        })) as unknown as PageResponse<OAuth2Application[]>;
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'YdInput',
        componentProps: {
          placeholder: t('oauth2.keywordPlaceholder'),
          'aria-label': t('oauth2.keyword'),
        },
        fieldName: 'keyword',
        label: t('oauth2.keyword'),
      },
      {
        component: 'YdSelectBase',
        componentProps: {
          placeholder: t('page.status'),
          options: [
            { label: t('page.enabled'), value: 'ENABLED' },
            { label: t('page.disabled'), value: 'DISABLED' },
          ],
        },
        fieldName: 'status',
        label: t('page.status'),
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: t('page.search') },
    resetButtonOptions: { content: t('page.reset') },
  },
});

// ========== 表单弹窗 ==========
const formRef = ref();
const isEdit = ref(false);

interface OAuth2FormState {
  id: string;
  clientId: string;
  clientName: string;
  clientType: string;
  redirectUrisText: string;
  allowedScopesText: string;
  allowedAudiencesText: string;
  description: string;
  sort?: number;
}

const formData = reactive<OAuth2FormState>({
  id: '',
  clientId: '',
  clientName: '',
  clientType: 'CONFIDENTIAL',
  redirectUrisText: '',
  allowedScopesText: '',
  allowedAudiencesText: '',
  description: '',
  sort: 0,
});

const rules = {
  clientId: [{ required: true, message: t('oauth2.clientIdRequired'), trigger: 'blur' }],
  clientName: [{ required: true, message: t('oauth2.clientNameRequired'), trigger: 'blur' }],
  redirectUrisText: [{ required: true, message: t('oauth2.redirectUrisRequired'), trigger: 'blur' }],
};

const [Modal, modalApi] = useYdModal({
  onOpenChange: async (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: OAuth2Application }>();
    if (data?.record?.clientId) {
      isEdit.value = true;
      try {
        const detail = (await getById({ id: data.record.clientId })) as unknown as OAuth2Application;
        Object.assign(formData, {
          id: detail.clientId ?? '',
          clientId: detail.clientId ?? '',
          clientName: detail.clientName ?? '',
          clientType: detail.clientType ?? 'CONFIDENTIAL',
          redirectUrisText: (detail.redirectUris ?? []).join('\n'),
          allowedScopesText: (detail.allowedScopes ?? []).join('\n'),
          allowedAudiencesText: (detail.allowedAudiences ?? []).join('\n'),
          description: detail.description ?? '',
        });
      } catch (error) {
        logger.warn('获取 OAuth2 应用详情失败: {}', error);
      }
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        id: '',
        clientId: '',
        clientName: '',
        clientType: 'CONFIDENTIAL',
        redirectUrisText: '',
        allowedScopesText: '',
        allowedAudiencesText: '',
        description: '',
        sort: 0,
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch (error) {
      logger.warn('表单校验失败: {}', error);
      return;
    }
    modalApi.lock();
    try {
      const parseList = (text: string) =>
        text
          .split('\n')
          .map((s) => s.trim())
          .filter(Boolean);

      const payload: Record<string, unknown> = {
        clientId: formData.clientId,
        clientName: formData.clientName,
        clientType: formData.clientType,
        redirectUris: parseList(formData.redirectUrisText),
        allowedScopes: parseList(formData.allowedScopesText),
        allowedAudiences: parseList(formData.allowedAudiencesText),
        description: formData.description,
        sort: formData.sort,
      };
      if (isEdit.value) {
        await update({ id: formData.id }, payload);
        showToast.success(t('page.updateSuccess'));
      } else {
        await register(payload);
        showToast.success(t('page.createSuccess'));
      }
      modalApi.close();
      gridApi.query();
    } catch (error) {
      logger.warn('保存 OAuth2 应用失败: {}', error);
    } finally {
      modalApi.unlock();
    }
  },
});

const modalTitle = computed(() => (isEdit.value ? t('oauth2.editTitle') : t('oauth2.createTitle')));

function handleAdd() {
  modalApi.setData({});
  modalApi.open();
}

function handleEdit(row: OAuth2Application) {
  modalApi.setData({ record: row });
  modalApi.open();
}

async function handleResetSecret(row: OAuth2Application) {
  if (!row.clientId) return;
  const appName = row.clientName ?? row.clientId;
  try {
    await YdConfirm(
      t('oauth2.resetSecretConfirm', { name: appName }),
      t('oauth2.resetSecret'),
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    const result = (await resetSecret({ id: row.clientId })) as unknown as Pick<OAuth2Application, 'clientSecret'>;
    showToast.success(t('oauth2.newSecretHint', { secret: result.clientSecret ?? '' }));
    gridApi.query();
  } catch (error) {
    logger.warn('重置密钥失败: {}', error);
  }
}

async function handleDelete(row: OAuth2Application) {
  if (!row.clientId) return;
  const appName = row.clientName ?? row.clientId;
  try {
    await YdConfirm(
      t('oauth2.deleteConfirm', { name: appName }),
      t('oauth2.deleteTitle'),
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    await deleteApi({ id: row.clientId });
    showToast.success(t('page.deleteSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除 OAuth2 应用失败: {}', error);
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('oauth2.title')">
      <template #toolbar-tools>
        <YdButton variant="default" @click="handleAdd">{{ t('oauth2.create') }}</YdButton>
      </template>
    </Grid>

    <!-- 创建/编辑弹窗 -->
    <Modal :title="modalTitle">
      <YdForm
        ref="formRef"
        :model="formData"
        :rules="rules"
        label-width="110px"
        label-position="right"
      >
        <YdFormItem label="Client ID" prop="clientId">
          <YdInput
            v-model="formData.clientId"
            :placeholder="t('oauth2.clientIdPlaceholder')"
            :disabled="isEdit"
          />
        </YdFormItem>
        <YdFormItem :label="t('oauth2.clientName')" prop="clientName">
          <YdInput v-model="formData.clientName" :placeholder="t('oauth2.clientNameRequired')" />
        </YdFormItem>
        <YdFormItem :label="t('oauth2.clientType')">
          <YdRadioGroup v-model="formData.clientType">
            <YdRadioGroupItem value="CONFIDENTIAL">{{ t('oauth2.confidential') }}</YdRadioGroupItem>
            <YdRadioGroupItem value="PUBLIC">{{ t('oauth2.public') }}</YdRadioGroupItem>
          </YdRadioGroup>
        </YdFormItem>
        <YdFormItem :label="t('oauth2.redirectUris')" prop="redirectUrisText">
          <YdInput
            v-model="formData.redirectUrisText"
            type="textarea"
            :rows="3"
            :placeholder="t('oauth2.redirectUrisPlaceholder')"
          />
        </YdFormItem>
        <YdFormItem :label="t('oauth2.scopes')">
          <YdInput
            v-model="formData.allowedScopesText"
            type="textarea"
            :rows="2"
            :placeholder="t('oauth2.scopesPlaceholder')"
          />
        </YdFormItem>
        <YdFormItem :label="t('oauth2.audiences')">
          <YdInput
            v-model="formData.allowedAudiencesText"
            type="textarea"
            :rows="2"
            :placeholder="t('oauth2.audiencesPlaceholder')"
          />
        </YdFormItem>
        <YdFormItem :label="t('page.sort')">
          <YdNumberFieldInput v-model="formData.sort" :min="0" :max="999" />
        </YdFormItem>
        <YdFormItem :label="t('page.description')">
          <YdInput
            v-model="formData.description"
            type="textarea"
            :rows="2"
            :placeholder="t('oauth2.descriptionPlaceholder')"
          />
        </YdFormItem>
      </YdForm>
    </Modal>
  </Page>
</template>
